<script setup lang="ts">
const props=defineProps<{projectId:string;admin?:boolean}>()
const emit=defineEmits<{changed:[]}>()
type Version={id:string;resourceId:string;number:number;fileKey:string;title:string;state:string;createdAt:string;reviewer?:string;reviewedAt?:string;coverId?:string;screenCount:number}
type Screen={id:string;name:string;width:number;height:number}
type Annotation={id:string;screenId:string;x:number;y:number;body:string;author:string;resolved:number;createdAt:string}
type Reply={id:string;annotationId:string;body:string;author:string;createdAt:string}
const versions=ref<Version[]>([]),screens=ref<Screen[]>([]),annotations=ref<Annotation[]>([]),replies=ref<Reply[]>([])
const error=ref(''),busy=ref(false),loading=ref(false),importing=ref(false),viewer=ref(false)
const url=ref(''),target=ref(''),selected=ref<string[]>([])
const source=ref<{name:string;version:string;fileKey:string;screens:{id:string;name:string;page:string;width:number;height:number}[]}|null>(null)
const versionId=ref(''),screenId=ref(''),zoom=ref(.65),annotating=ref(false),imageReady=ref(false),imageFailed=ref(false)
const active=ref(''),draft=ref<{x:number;y:number}|null>(null),message=ref(''),reply=ref(''),showResolved=ref(false)
const version=computed(()=>versions.value.find(v=>v.id===versionId.value))
const screen=computed(()=>screens.value.find(s=>s.id===screenId.value))
const screenIndex=computed(()=>screens.value.findIndex(s=>s.id===screenId.value))
function moveScreen(direction:number){
 if(loading.value || busy.value)return
 const next=screens.value[screenIndex.value+direction]
 if(next)screenId.value=next.id
}
const latest=computed(()=>versions.value.filter((v,i,arr)=>arr.findIndex(x=>x.resourceId===v.resourceId)===i))
const history=computed(()=>versions.value.filter(v=>v.resourceId===version.value?.resourceId))
const pins=computed(()=>annotations.value.filter(a=>a.screenId===screenId.value))
const visiblePins=computed(()=>pins.value.filter(a=>showResolved.value||!a.resolved))
const commentsOpen=ref(false),mobilePagesOpen=ref(false)
const displayName=(name:string)=>name.replace(/^(Page|Mobile)\s*\/\s*/, '').replace(/\s*\(modèle[^)]*\)/,'')
function chooseScreen(id:string){if(busy.value||loading.value)return;screenId.value=id;mobilePagesOpen.value=false}
function toggleAnnotations(){annotating.value=!annotating.value;draft.value=null;if(annotating.value)commentsOpen.value=true}
watch(commentsOpen,async()=>{await nextTick();fit()})
const isLatest=computed(()=>latest.value.some(v=>v.id===versionId.value))
const states:Record<string,string>={pending:'Avis attendu',approved:'Validée',changes:'Modifications demandées'}
const date=(value:string)=>new Date(value).toLocaleDateString('fr-FR',{day:'numeric',month:'short'})
const fail=(e:any)=>{error.value=e?.data?.statusMessage||'Action impossible. Réessayez.'}
let request=0
async function load(detail=false){
 const id=++request;loading.value=true
 try{const data=await $fetch<{versions:Version[];screens?:Screen[];annotations?:Annotation[];replies?:Reply[]}>('/api/portal/mockups',{query:{projectId:props.projectId,...(detail?{versionId:versionId.value}:{})}})
 if(id!==request)return
 versions.value=data.versions
 if(detail){screens.value=data.screens||[];annotations.value=data.annotations||[];replies.value=data.replies||[];if(!screens.value.some(s=>s.id===screenId.value))screenId.value=screens.value[0]?.id||''}
 }catch(e){if(id===request)fail(e)}finally{if(id===request)loading.value=false}
}
watch(()=>props.projectId,()=>{viewer.value=false;importing.value=false;versionId.value='';source.value=null;load()},{immediate:true})
watch(screenId,async()=>{draft.value=null;active.value='';message.value='';reply.value='';imageReady.value=false;imageFailed.value=false;await nextTick();fit();canvas.value?.scrollTo({top:0,left:0,behavior:'instant'})})
watch(url,()=>{source.value=null;selected.value=[]})
function startImport(v?:Version){target.value=v?.resourceId||'';url.value=v?`https://www.figma.com/design/${v.fileKey}`:'';source.value=null;selected.value=[];importing.value=true;error.value=''}
async function inspect(){busy.value=true;error.value='';try{source.value=await $fetch('/api/portal/mockups/inspect',{method:'POST',body:{url:url.value}});selected.value=[]}catch(e){fail(e)}finally{busy.value=false}}
async function publish(){if(!source.value)return;busy.value=true;error.value='';try{const result=await $fetch<{versionId:string}>('/api/portal/mockups/publish',{method:'POST',body:{projectId:props.projectId,url:url.value,resourceId:target.value,sourceVersion:source.value.version,nodeIds:selected.value}});importing.value=false;await load();emit('changed');await open(result.versionId)}catch(e){fail(e)}finally{busy.value=false}}
async function open(id:string){confirmReview.value=false;annotating.value=false;commentsOpen.value=false;mobilePagesOpen.value=false;versionId.value=id;screenId.value='';screens.value=[];annotations.value=[];replies.value=[];active.value='';draft.value=null;viewer.value=true;error.value='';await load(true);await nextTick();fit()}
const canvas=ref<HTMLElement|null>(null),dialog=ref<HTMLElement|null>(null)
let focusBefore:HTMLElement|null=null
watch(viewer,async value=>{if(value){focusBefore=document.activeElement as HTMLElement;await nextTick();dialog.value?.focus()}else focusBefore?.focus()})
function trap(event:KeyboardEvent){if(event.key==='Escape'){viewer.value=false;return}if(event.key!=='Tab')return;const elements=dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),textarea,select,a[href],input');if(!elements?.length)return;const first=elements[0]!,last=elements[elements.length-1]!;if(event.shiftKey&&(document.activeElement===first||document.activeElement===dialog.value)){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
function fit(){
 if(!screen.value || !canvas.value)return
 const style=getComputedStyle(canvas.value)
 const padding=parseFloat(style.paddingLeft)+parseFloat(style.paddingRight)
 zoom.value=Math.max(.05,Math.min(1,(canvas.value.clientWidth-padding)/screen.value.width))
}
function place(event:MouseEvent){if(!annotating.value||!imageReady.value)return;const bounds=(event.currentTarget as HTMLElement).getBoundingClientRect();draft.value={x:Math.max(0,Math.min(1,(event.clientX-bounds.left)/bounds.width)),y:Math.max(0,Math.min(1,(event.clientY-bounds.top)/bounds.height))};active.value='';message.value=''}
function selectPin(a:Annotation){commentsOpen.value=true;active.value=a.id;draft.value=null;reply.value=''}
async function comment(action:'create'|'reply'|'resolve',resolved?:boolean){busy.value=true;error.value='';try{await $fetch('/api/portal/mockups/comment',{method:'POST',body:{action,projectId:props.projectId,versionId:versionId.value,screenId:screenId.value,annotationId:active.value,...draft.value,body:action==='create'?message.value:reply.value,resolved}});draft.value=null;message.value='';reply.value='';await load(true);emit('changed')}catch(e){fail(e)}finally{busy.value=false}}
const confirmReview=ref(false)
async function review(state:string){busy.value=true;error.value='';try{await $fetch('/api/portal/mockups/review',{method:'POST',body:{projectId:props.projectId,versionId:versionId.value,state}});confirmReview.value=false;await load(true);emit('changed')}catch(e){fail(e)}finally{busy.value=false}}
</script>
<template>
 <section class="mk">
  <header class="mk-heading"><div><h2>Maquettes</h2><p>Vos écrans, vos retours et chaque version au même endroit.</p></div><button v-if="admin" class="primary" @click="startImport()">+ Importer depuis Figma</button></header>
  <p v-if="error && !viewer" role="alert" class="notice">{{error}}</p>
  <form v-if="importing" class="importer" @submit.prevent="inspect">
   <header><h3>{{target?'Publier une nouvelle version':'Importer un fichier Figma'}}</h3><button type="button" :disabled="busy" @click="importing=false">Fermer</button></header>
   <label>Lien du fichier Figma<input v-model="url" type="url" required placeholder="https://www.figma.com/design/…" :disabled="busy || !!target"></label>
   <button :disabled="busy" type="submit">{{busy?'Chargement…':'Charger les écrans'}}</button>
   <template v-if="source"><div class="selection-head"><strong>{{source.name}}</strong><span>{{selected.length}} écran(s) sélectionné(s) sur {{source.screens.length}}</span></div><div class="screen-picker"><label v-for="s in source.screens" :key="s.id"><input v-model="selected" type="checkbox" :value="s.id" :disabled="busy"><span>{{s.name}}<small>{{s.page}} · {{Math.round(s.width)}} × {{Math.round(s.height)}}</small></span></label></div><p v-if="!source.screens.length">Aucun cadre exportable trouvé. Placez les écrans dans une page ou une section Figma.</p><p>Une copie de ces écrans sera publiée dans l’espace client. Les anciennes versions et leurs commentaires seront conservés.</p><button type="button" class="primary" :disabled="busy || !selected.length" @click="publish">{{busy?'Export et publication en cours…':'Publier '+selected.length+' écran(s)'}}</button></template>
  </form>
  <p v-if="loading && !viewer" role="status">Chargement des maquettes…</p>
  <div v-else-if="!latest.length" class="empty"><UIcon name="i-tabler-layout"/><h3>Les maquettes arrivent ici.</h3><p>{{admin?'Importez un fichier Figma et choisissez les écrans à partager.':'Vous pourrez parcourir les écrans et cliquer dessus pour laisser vos retours.'}}</p></div>
  <div v-else class="collection-grid"><article v-for="v in latest" :key="v.id" class="collection-card"><button class="collection-cover" :aria-label="'Ouvrir les maquettes '+v.title" @click="open(v.id)"><img v-if="v.coverId" :src="`/api/portal/mockups/screens/${v.coverId}`" :alt="'Aperçu de '+v.title" loading="lazy"><span v-else class="cover-placeholder"><UIcon name="i-tabler-layout"/></span><span class="cover-open"><UIcon name="i-tabler-arrow-up-right"/></span></button><div class="collection-info"><div><h3>{{v.title}}</h3><p>{{v.screenCount}} pages · Version {{v.number}} · {{date(v.createdAt)}}</p></div><span class="badge">{{states[v.state]}}</span></div><div class="collection-actions"><button v-if="admin" @click="startImport(v)">Nouvelle version</button><button class="primary" @click="open(v.id)">Explorer les maquettes <UIcon name="i-tabler-arrow-right"/></button></div></article></div>
  <Teleport to="body"><section v-if="viewer" ref="dialog" class="mk mk-viewer" :class="{'has-comments':commentsOpen}" role="dialog" aria-modal="true" aria-label="Visionneuse des maquettes" tabindex="-1" @keydown="trap">
   <header class="viewer-header"><div><button class="back-to-portal" aria-label="Fermer la visionneuse" @click="viewer=false"><UIcon name="i-tabler-arrow-left"/>Retour au portail</button><span class="header-divider">/</span><strong>{{version?.title}}</strong></div><div class="actions"><PortalThemeToggle /><span class="badge">{{states[version?.state||'pending']}}</span><label class="sr-only" for="mockup-version">Version</label><select id="mockup-version" :value="versionId" :disabled="busy||loading" @change="confirmReview=false;open(($event.target as HTMLSelectElement).value)"><option v-for="v in history" :key="v.id" :value="v.id">Version {{v.number}} · {{date(v.createdAt)}}</option></select></div></header>
   <div class="viewer-toolbar"><div class="screen-navigation" role="group" aria-label="Navigation entre les maquettes"><button class="mobile-page-toggle" :aria-expanded="mobilePagesOpen" aria-controls="mockup-page-nav" @click="mobilePagesOpen=!mobilePagesOpen"><UIcon name="i-tabler-menu-2"/>Pages</button><button type="button" class="screen-arrow" aria-label="Page précédente" title="Page précédente" :disabled="loading || busy || screenIndex<=0" @click="moveScreen(-1)"><UIcon name="i-tabler-chevron-left"/></button><span class="screen-count" aria-live="polite">{{screenIndex+1}} / {{screens.length}}</span><button type="button" class="screen-arrow" aria-label="Page suivante" title="Page suivante" :disabled="loading || busy || screenIndex<0 || screenIndex>=screens.length-1" @click="moveScreen(1)"><UIcon name="i-tabler-chevron-right"/></button></div><div class="actions"><div class="zoom-controls"><button aria-label="Réduire" @click="zoom=Math.max(.05,zoom/1.25)">−</button><span>{{Math.round(zoom*100)}}%</span><button aria-label="Agrandir" @click="zoom=Math.min(3,zoom*1.25)">+</button><button @click="fit">Ajuster</button></div><button :class="{primary:annotating}" :disabled="!imageReady" :aria-pressed="annotating" @click="toggleAnnotations"><UIcon name="i-tabler-message-plus"/>{{annotating?'Annotation activée':'Annoter'}}</button><button :aria-expanded="commentsOpen" aria-controls="mockup-discussion" @click="commentsOpen=!commentsOpen;annotating=false"><UIcon name="i-tabler-messages"/>Commentaires <span>{{annotations.length}}</span></button></div></div>
   <p v-if="error" class="notice" role="alert">{{error}}</p>
   <div class="viewer-body"><aside id="mockup-page-nav" class="page-sidebar" :class="{'mobile-open':mobilePagesOpen}"><div class="page-sidebar-title"><strong>{{version?.title}}</strong><p>{{screens.length}} pages à découvrir</p></div><nav aria-label="Pages de la maquette"><button v-for="(s,i) in screens" :key="s.id" :class="{active:screenId===s.id}" :aria-current="screenId===s.id?'page':undefined" :disabled="busy || loading" @click="chooseScreen(s.id)"><span>{{String(i+1).padStart(2,'0')}}</span>{{displayName(s.name)}}</button></nav><div class="page-sidebar-footer"><span>MC Studio</span><p>Design & développement</p><button v-if="!admin && isLatest" class="primary" :disabled="busy || version?.state==='approved'" @click="commentsOpen=true;confirmReview=true">{{version?.state==='approved'?'Version validée':'Valider cette version'}}<UIcon name="i-tabler-check"/></button></div></aside><div ref="canvas" class="canvas"><p v-if="loading" role="status">Chargement…</p><p v-if="imageFailed" role="alert">Impossible de charger cet écran. Fermez et rouvrez la maquette.</p><header v-if="screen" class="page-intro"><div><h2>{{displayName(screen.name)}}</h2><p>Explorez la maquette et partagez vos retours avec MC Studio.</p></div><a :href="`/api/portal/mockups/screens/${screen.id}`" :download="displayName(screen.name)+'.png'" aria-label="Télécharger cette maquette en PNG" title="Télécharger en PNG"><UIcon name="i-tabler-download"/></a></header><div v-if="screen" class="artboard" :class="{annotating}" :style="{width:screen.width*zoom+'px',height:screen.height*zoom+'px'}" @click="place"><img :key="screen.id" :src="`/api/portal/mockups/screens/${screen.id}`" :alt="screen.name" draggable="false" @load="imageReady=true" @error="imageFailed=true"><button v-for="a in visiblePins" :key="a.id" class="pin" :class="{selected:active===a.id,resolved:a.resolved}" :style="{left:a.x*100+'%',top:a.y*100+'%'}" :aria-label="'Annotation '+(pins.indexOf(a)+1)+' : '+a.body" @click.stop="selectPin(a)">{{pins.indexOf(a)+1}}</button><span v-if="draft" class="pin draft" :style="{left:draft.x*100+'%',top:draft.y*100+'%'}">+</span></div></div>
   <aside v-if="commentsOpen" id="mockup-discussion" class="discussion"><header><button class="discussion-close" aria-label="Fermer les commentaires" @click="commentsOpen=false;annotating=false">×</button><h3>Commentaires <span>{{pins.length}}</span></h3><label class="check"><input v-model="showResolved" type="checkbox">Afficher les résolus</label></header><p v-if="!isLatest" class="notice">Version précédente : les retours restent attachés à ces écrans.</p><p v-if="annotating && !draft" class="hint">Cliquez sur un élément de la maquette pour y déposer un commentaire.</p><button v-if="annotating && !draft" :disabled="!imageReady" @click="draft={x:.5,y:.5};active=''">Annoter au centre de l’écran</button>
    <form v-if="draft" class="comment-form" @submit.prevent="comment('create')"><h3>Nouvelle annotation</h3><label>Votre commentaire<textarea v-model="message" autofocus required maxlength="3000" rows="4" placeholder="Que souhaitez-vous ajuster ici ?"/></label><div class="actions"><button type="button" @click="draft=null">Annuler</button><button class="primary" :disabled="busy || !message.trim()">Publier</button></div></form>
    <p v-if="!visiblePins.length && !draft" class="hint">Aucun commentaire {{showResolved?'':'ouvert'}} sur cet écran.</p>
    <article v-for="a in visiblePins" :key="a.id" class="comment" :class="{active:active===a.id}"><button class="comment-title" @click="selectPin(a)"><span class="number">{{pins.indexOf(a)+1}}</span><strong>{{a.author}}</strong><small>{{date(a.createdAt)}}{{a.resolved?' · Résolu':''}}</small></button><p>{{a.body}}</p><template v-if="active===a.id"><div v-for="r in replies.filter(r=>r.annotationId===a.id)" :key="r.id" class="reply"><strong>{{r.author}}</strong><small>{{date(r.createdAt)}}</small><p>{{r.body}}</p></div><form @submit.prevent="comment('reply')"><label class="sr-only" :for="'reply-'+a.id">Répondre</label><textarea :id="'reply-'+a.id" v-model="reply" required maxlength="3000" rows="2" placeholder="Répondre…"/><div class="actions"><button type="button" :disabled="busy" @click="comment('resolve',!a.resolved)">{{a.resolved?'Rouvrir':'Marquer résolu'}}</button><button :disabled="busy || !reply.trim()">Répondre</button></div></form></template><button v-else class="text-button" @click="selectPin(a)">Ouvrir la discussion · {{replies.filter(r=>r.annotationId===a.id).length}} réponse(s)</button></article>
    <footer><p v-if="version?.reviewer">{{states[version.state]}} par {{version.reviewer}} · {{date(version.reviewedAt!)}}</p><template v-if="!admin && isLatest"><template v-if="confirmReview"><p>Confirmer la validation de la version {{version?.number}} ? {{annotations.filter(a=>!a.resolved).length}} annotation(s) encore ouverte(s).</p><div class="actions"><button @click="confirmReview=false">Annuler</button><button class="primary" :disabled="busy" @click="review('approved')">Confirmer la validation</button></div></template><div v-else class="review-actions"><button :disabled="busy" @click="review('changes')">Demander des modifications</button><button class="primary" :disabled="busy || version?.state==='approved'" @click="confirmReview=true">Valider cette version</button></div></template></footer>
   </aside></div>
  </section></Teleport>
 </section>
</template>
<style scoped>
